#include <stdio.h>
struct Point { int x; int y; };
void move(struct Point *p, int dx, int dy) {
    p->x += dx;
    p->y += dy;
}
int main() {
    struct Point pts[3] = {{1,2},{3,4},{5,6}};
    struct Point *p = pts + 1;
    move(p, 10, -1);
    p++;
    move(p, -2, 5);
    printf("%d %d %d %d", pts[1].x, pts[1].y, pts[2].x, pts[2].y);
    return 0;
}

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

print(bubble_sort([5, 3, 8, 1, 9, 2]))

